function cm_import_page(){if(!current_user_can('manage_options'))return; if(isset($_POST['cm_import_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cm_import_nonce'])),'cm_import')){ $count=0; foreach(cm_seed_projects() as $p){if(get_page_by_title($p[0],OBJECT,'cm_project'))continue;$id=wp_insert_post(['post_type'=>'cm_project','post_title'=>$p[0],'post_excerpt'=>$p[4],'post_status'=>'publish','menu_order'=>$count]);if($id&&!is_wp_error($id)){update_post_meta($id,'cm_external_url',$p[5]);update_post_meta($id,'cm_category_label',$p[1]);update_post_meta($id,'cm_tag',$p[2]);update_post_meta($id,'cm_platform',str_contains($p[1],'E-commerce')?'E-commerce':'Website');$count++;}} foreach(cm_seed_services() as $s){if(get_page_by_title($s[0],OBJECT,'cm_service'))continue;wp_insert_post(['post_type'=>'cm_service','post_title'=>$s[0],'post_content'=>$s[1],'post_status'=>'publish']);} echo '<div class="notice notice-success"><p>Imported '.$count.' portfolio projects. Add featured images from the Media Library after upload.</p></div>'; } ?><div class="wrap"><h1>CartMakers Content Importer</h1><p>This seeds the known CartMakers portfolio and service titles. It does not overwrite existing entries or upload files.</p><form method="post"><?php wp_nonce_field('cm_import','cm_import_nonce'); submit_button('Import Existing Content'); ?></form></div><?php}
